const IMPORT_FIELDS=['Bank','CardName','CardType','Last4','Network','CreditLimit','AvailableLimit','UsedLimit','BillingDate','DueDate','AnnualFee','Status','CardExpiry','FD','FDRate','FDInterest','CashbackRate','CashbackCap','CashbackEarned','TotalReturn','TotalROI','Notes'];
const IMPORT_TEMPLATE='Bank,CardName,CardType,Last4,CVV,Network,CreditLimit,AvailableLimit,UsedLimit,BillingDate,DueDate,AnnualFee,Status,CardExpiry,FD,FDRate,FDInterest,CashbackRate,CashbackCap,CashbackEarned,TotalReturn,TotalROI,Notes\r\nSBM India,Novio,FD Backed Credit Card,1234,,Visa,9000,0,9000,1st of every Month,Bill Date + 15 Days,0,ACTIVE,11/30,10000,6.5%,650,2%,180,180,2810,28.10%,Sample record';
function parseCardCsv(text){
 const rows=[];let row=[],cell='',quoted=false;
 for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'&&quoted&&next==='"'){cell+='"';i++;}else if(ch==='"'){quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&next==='\n')i++;row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row);row=[];cell='';}else cell+=ch;}
 row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row);
 if(rows.length<2)throw new Error('The selected file has no card rows.');
 const headers=rows[0].map(h=>String(h||'').trim());
 const aliases={'Card Type':'CardType','Card Expiry':'CardExpiry','Credit Limit':'CreditLimit','Available Limit':'AvailableLimit','Annual Fee':'AnnualFee','CC Name':'CardName','App Name':'Notes','Bank Name':'Bank','CC No.':'Last4','CC No':'Last4','Card Number':'Last4','CC Exp':'CardExpiry','Exp':'CardExpiry','Bill date':'BillingDate','Bill Date':'BillingDate','Due date':'DueDate','Due Date':'DueDate','Limit':'CreditLimit','Using limit':'UsedLimit','Max Cashback capable':'CashbackCap','Cashback Rate':'CashbackRate','Cashback':'CashbackEarned','FD Rate':'FDRate','FD Interest':'FDInterest','Total Return':'TotalReturn','Total ROI':'TotalROI'};
 return rows.slice(1).map((r,index)=>{const item={};headers.forEach((h,i)=>{const key=aliases[h]||h;if(IMPORT_FIELDS.includes(key)){let v=String(r[i]??'').trim();if(key==='Last4')v=v.replace(/\D/g,'').slice(-4);if(v)item[key]=v;}});if(!item.Bank||!item.CardName)throw new Error('Row '+(index+2)+': Bank and CardName are required.');if(item.Last4&&item.Last4.length!==4)throw new Error('Row '+(index+2)+': Last4 must contain four digits.');return item;});
}
function nextMonthlyBillDate(value,now=new Date()){
 const raw=String(value||'').trim();if(!raw)return null;
 const direct=raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);
 if(direct){const d=new Date(Number(direct[1]),Number(direct[2])-1,Number(direct[3]));if(!Number.isNaN(d.getTime()))return d;}
 const match=raw.match(/\b(\d{1,2})(?:st|nd|rd|th)?\b/i);if(!match)return null;
 const day=Number(match[1]);if(day<1||day>31)return null;
 const today=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 let candidate=new Date(today.getFullYear(),today.getMonth(),Math.min(day,new Date(today.getFullYear(),today.getMonth()+1,0).getDate()));
 if(candidate<today){const y=today.getMonth()===11?today.getFullYear()+1:today.getFullYear(),m=(today.getMonth()+1)%12;candidate=new Date(y,m,Math.min(day,new Date(y,m+1,0).getDate()));}
 return candidate;
}
