 const[password,setPassword]=useState(''),[page,setPage]=useState('Home'),[cards,setCards]=useState([]),[bills,setBills]=useState([]),[rules,setRules]=useState([]),[loading,setLoading]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[modal,setModal]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState(emptyCard),[saving,setSaving]=useState(false),[selected,setSelected]=useState(null),[showDetails,setShowDetails]=useState(false),[importOpen,setImportOpen]=useState(false),[importRows,setImportRows]=useState([]),[importFile,setImportFile]=useState(null),[importBusy,setImportBusy]=useState(false),[pdfBusy,setPdfBusy]=useState(false),[transactions,setTransactions]=useState([]),[txnModal,setTxnModal]=useState(false),[txnSaving,setTxnSaving]=useState(false),[statementOpen,setStatementOpen]=useState(false),[statementPeriodType,setStatementPeriodType]=useState('Monthly'),[statementMonth,setStatementMonth]=useState(new Date().toISOString().slice(0,7)),[statementFy,setStatementFy]=useState(String(new Date().getMonth()>=3?new Date().getFullYear():new Date().getFullYear()-1)),[statementFrom,setStatementFrom]=useState(new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10)),[statementTo,setStatementTo]=useState(new Date().toISOString().slice(0,10)),[statementStatus,setStatementStatus]=useState('All status'),[statementFormat,setStatementFormat]=useState('PDF'),[statementBusy,setStatementBusy]=useState(false),[billPayOpen,setBillPayOpen]=useState(false),[billPayCardID,setBillPayCardID]=useState(''),[billPayAmount,setBillPayAmount]=useState(''),[billPayBusy,setBillPayBusy]=useState(false),[billPayNotes,setBillPayNotes]=useState(''),[txnForm,setTxnForm]=useState({CardID:'',Merchant:'',Amount:'',Category:'Purchase',TransactionDate:new Date().toISOString().slice(0,10),ReferenceNumber:'',Notes:''});
